from akasha.document import DocumentField, PayloadValue
from akasha.storage.memtable import MemTable
from std.collections.string.string_span import StringSpan
from std.testing import assert_equal


def _string_address(value: String) -> Int:
    # The immutable argument prevents a mutable StringSpan from detaching COW.
    return Int(StringSpan(value).unsafe_ptr())


def main() raises:
    for width in [0, 32, 4096, 1048576, 8388608]:
        var table = MemTable(2)
        var fields: List[DocumentField] = [
            DocumentField("body", PayloadValue.string("x" * width))
        ]
        table.apply_document_upsert(-7, 1, [1.0, 2.0], fields^)
        var owned = table.get(-7)
        ref entry = table.entry_ref_at(0)
        var same_string = (
            _string_address(entry.fields()[0].value._string_value)
            == _string_address(owned.value().fields[0].value._string_value)
        )
        var same_vector = (
            Int(entry.values().unsafe_ptr())
            == Int(owned.value().vector.unsafe_ptr())
        )
        var same_fields = (
            Int(entry.fields().unsafe_ptr())
            == Int(owned.value().fields.unsafe_ptr())
        )
        owned.value().vector[0] = 9.0
        owned.value().fields[0].value._string_value += "y"
        assert_equal(entry.values()[0], Float32(1))
        assert_equal(entry.fields()[0].value._string_value, "x" * width)
        assert_equal(owned.value().fields[0].value._string_value, "x" * width + "y")
        print("width", width, "same_string", same_string, "same_vector", same_vector, "same_fields", same_fields)

